import React from 'react';
import { Container, Stack } from '@fiverr-private/layout_components';
import { theme, hex2rgb } from '@fiverr-private/theme';
import { useCarouselContext } from '../Carousel/constants';
import type { SlidesIndicatorProps } from './types';
import { SLIDES_INDICATOR_ID } from './constants';
import { useDotsIndicators } from './useDotsIndicators';

const SlidesIndicator = ({ dataTrackTag = 'slides_indicator', ...restContainerProps }: SlidesIndicatorProps) => {
  const { currentPosition = -1, breakpoints, slides = [], supportSlidesIndicator } = useCarouselContext();
  const { edgeDotsIdx, hiddenDotsIdx } = useDotsIndicators({
    currentPosition,
    slidesToShow: breakpoints.default,
    slides,
  });

  if (!supportSlidesIndicator) {
    return null;
  }

  return (
    <Stack
      dataTrackTag={dataTrackTag}
      position="absolute"
      bottom={0}
      left="50%"
      transform="translateX(-50%)"
      height="32px"
      alignItems="center"
      justifyContent="center"
      zIndex="1"
      {...restContainerProps}
    >
      <Stack
        alignItems="center"
        columnGap="1.5"
        padding="1"
        borderRadius="sm"
        background={`rgba(${hex2rgb(theme.colors.grey_1100)}, .5)`}
      >
        {slides.map((_, index) => {
          const edgeDot = edgeDotsIdx.includes(index);
          const isActive = currentPosition === index;
          const hiddenDot = hiddenDotsIdx.includes(index);

          const getDotScale = () => {
            if (isActive) {
              return 1.6;
            }

            if (edgeDot) {
              return 0.8;
            }

            return 1;
          };

          return (
            <Container
              key={index}
              display="inlineBlock"
              width="5px"
              height="5px"
              backgroundColor="white"
              borderRadius="circle"
              hidden={hiddenDot}
              transform={`scale(${getDotScale()})`}
              marginX={isActive ? 'px' : undefined}
              opacity={isActive ? '1' : '0.5'}
              transition="transform .15s ease-in-out"
            />
          );
        })}
      </Stack>
    </Stack>
  );
};

SlidesIndicator.id = SLIDES_INDICATOR_ID;
SlidesIndicator.displayName = SLIDES_INDICATOR_ID;
export default SlidesIndicator;
